import Fastify, { type FastifyServerOptions, type FastifyInstance } from "fastify";
import autoLoad from "@fastify/autoload";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import {
  type ZodTypeProvider,
  serializerCompiler,
  validatorCompiler,
} from "fastify-type-provider-zod";
import fp from "fastify-plugin";
import fastifyCors from "@fastify/cors";
import ssePlugin from "@fastify/sse";
import type { SSEPluginOptions } from "@fastify/sse";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// CORS configuration for frontend integration, allowing credentials and specific headers
// Adjust the origin as needed for production
const corsOptions = {
  origin: ["http://localhost:3000", "http://localhost:5173"], // Replace with your frontend URL
  methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  allowedHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
  credentials: true,
  maxAge: 86400, // Cache preflight response for 24 hours
};

// Plugin version for serverless deployment
async function fastifyServerPlugin(fastify: FastifyInstance) {
  // Set the validator and serializer compilers
  fastify.setValidatorCompiler(validatorCompiler);
  fastify.setSerializerCompiler(serializerCompiler);

  await fastify.register(fastifyCors, {
    origin: corsOptions.origin,
    methods: corsOptions.methods,
    allowedHeaders: corsOptions.allowedHeaders,
    credentials: corsOptions.credentials,
    maxAge: corsOptions.maxAge,
  });

  // Register SSE plugin before routes so `sse: true` route config works
  const sseOptions: SSEPluginOptions = {
    heartbeatInterval: 30000,
  };
  await fastify.register(ssePlugin, sseOptions);

  // Auto-register API routes
  await fastify.register(autoLoad, {
    dir: join(__dirname, "routes"),
    routeParams: true,
  });
}



// Export as a Fastify plugin for serverless
export default fp(fastifyServerPlugin, {
  name: "fastify-server",
});

// Build function for standalone server
export async function buildServer(opt: FastifyServerOptions) {
  const fastify = Fastify(opt).withTypeProvider<ZodTypeProvider>();
  // Fastify automatically includes JSON body parsing for application/json content type
  await fastify.register(fastifyServerPlugin);
  return fastify;
}

import { createRouter, createRootRoute, createRoute } from "@tanstack/react-router"
import App from "./App"
import HomePage from "./pages/HomePage"
import NotificationPage from "./components/NotificationPage"
import NotificationPreferencesPage from "./pages/NotificationPreferencesPage"
import TransactionsPage from "./pages/TransactionsPage"
import TransactionDetailPage from "./pages/TransactionDetailPage"
import AccountPage from "./pages/AccountPage"
import AccountTransactionsPage from "./pages/AccountTransactionsPage"
import AccountDetailPage from "./pages/AccountDetailPage"
import AccountSettingsPage from "./pages/AccountSettingsPage"
import SearchPage from "./pages/SearchPage"

const rootRoute = createRootRoute({
  component: App,
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: HomePage,
})

const notificationsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/notifications",
  component: NotificationPage,
})

const notificationPreferencesRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/notifications/preferences",
  component: NotificationPreferencesPage,
})

const transactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/transactions",
  component: TransactionsPage,
})

const transactionDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/transactions/$transactionId",
  component: TransactionDetailPage,
})

const accountRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account",
  component: AccountPage,
})

const accountDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account/$accountNumber",
  component: AccountDetailPage,
})

const accountTransactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account/transactions",
  component: AccountTransactionsPage,
})

const accountSettingsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account/settings",
  component: AccountSettingsPage,
})

const searchRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/search",
  component: SearchPage,
})

const routeTree = rootRoute.addChildren([
  indexRoute,
  notificationsRoute,
  notificationPreferencesRoute,
  transactionsRoute,
  transactionDetailRoute,
  accountRoute,
  accountDetailRoute,
  accountTransactionsRoute,
  accountSettingsRoute,
  searchRoute,
])

const router = createRouter({ routeTree })

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router
  }
}

export { router, rootRoute }

