```ts
transferHandler = async (request, reply) => {
    // 1. Auth check via better-auth
    const session = await auth.api.getSession({ headers: fromNodeHeaders(request.headers) });
    if (!session) return sendError({ reply, statusCode: 401, message: "UNAUTHORIZED", ... });

    // 2. Parse and coerce account numbers to BigInt
    const { senderAccountNumber, receiverAccountNumber, ...rest } = request.body;
    const senderAccountBigInt = BigInt(senderAccountNumber) as TBankAccountNumber;
    const receiverAccountBigInt = BigInt(receiverAccountNumber) as TBankAccountNumber;

    // 3. Delegate to service
    const transaction = await this.walletService.transfer({
        ...rest, senderAccountNumber: senderAccountBigInt, receiverAccountNumber: receiverAccountBigInt,
    });

    // 4. Transform to DTO (amount /100 for cents->dollars, dates to ISO strings)
    sendSuccess<TWalletTransactionDTO>({ reply, statusCode: 201, data: toTransactionDTO(transaction) });
