## 5. FRONTEND ROUTER (TanStack Router)

### Route Tree Definition
**`/home/coderx85/Projects/Work/.GITHUB/wave/wave-main/client/src/router.tsx`**
```tsx
import { createRouter, createRootRoute, createRoute } from "@tanstack/react-router"

const rootRoute = createRootRoute({ component: App })

const routeTree = rootRoute.addChildren([
  indexRoute,                  // /               -> HomePage
  notificationsRoute,          // /notifications  -> NotificationPage
  notificationPreferencesRoute,// /notifications/preferences -> NotificationPreferencesPage
  transactionsRoute,           // /transactions   -> TransactionsPage
  transactionDetailRoute,      // /transactions/$transactionId -> TransactionDetailPage
  accountRoute,                // /account        -> AccountPage
  accountDetailRoute,          // /account/$accountNumber -> AccountDetailPage
  accountTransactionsRoute,    // /account/transactions -> AccountTransactionsPage
  accountSettingsRoute,        // /account/settings -> AccountSettingsPage
  searchRoute,                 // /search         -> SearchPage
])

const router = createRouter({ routeTree })
```

### Pattern for Adding a New Route
Each route follows this pattern:
```tsx
const performanceRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/performance",
  component: PerformancePage,
})
```
Then add it to `rootRoute.addChildren([...])`.

